// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;
    function setUp() public { c = new TimelockController(0, new address[](0), new address[](0)); }
    function testFuzz_property(bytes32 role1, bytes32 role2) public {
        vm.assume(role1 != role2);
        bytes32 special = keccak256("TIMELOCK_ADMIN_ROLE");
        vm.assume(role1 != special && role2 != special);
        vm.assume(role1 != keccak256("PROPOSER_ROLE") && role2 != keccak256("PROPOSER_ROLE"));
        vm.assume(role1 != keccak256("EXECUTOR_ROLE") && role2 != keccak256("EXECUTOR_ROLE"));
        vm.assume(role1 != bytes32(0) && role2 != bytes32(0));
        assertTrue(c.getRoleAdmin(role1) == c.getRoleAdmin(role2));
    }
}
